/*
 * Bootstrap's default (left-to-right) build, for the styles.scss entry point.
 */
@import "node_modules/bootstrap/dist/css/bootstrap.css";

@use "sass:meta";

/*
 * Application styles shared by the two stylesheet entry points, styles.scss
 * (left-to-right) and styles-rtl.scss (right-to-left). The only difference
 * between the two is which Bootstrap build they load first: Bootstrap's default
 * build is physical (`.ms-*` is a margin-left, `.text-start` is a
 * text-align: left), so right-to-left languages need the RTL build instead.
 */
// bs variables
$grid-gutter-width: 1.5rem;
$border-radius: .375rem;
$btn-border-width: var(--bs-border-width);

$form-file-button-bg: var(--bs-body-bg);
$form-file-button-hover-bg: var(--pngx-bg-alt);

@include meta.load-css("theme");
@import "@ng-select/ng-select/themes/default.theme.css";
@include meta.load-css("print");

// re-created bootstrap styles
.mt-n2 {
  margin-top: -0.5rem;
}
.me-n2 {
  margin-inline-end: -0.5rem;
}
.me-n3 {
  margin-inline-end: -1rem;
}
.mb-n2 {
  margin-bottom: -0.5rem;
}
.ms-n1 {
  margin-inline-start: -0.25rem;
}
.ms-n2 {
  margin-inline-start: -0.5rem;
}
.my-n2 {
  margin-top: -0.5rem;
  margin-bottom: -0.5rem;
}

$grid-breakpoints: (
  xs: 0,
  sm: 576px,
  md: 768px,
  lg: 992px,
  xl: 1200px,
  xxl: 1400px,
  xxxl: 2400px
);

:root {
  @each $name, $value in $grid-breakpoints {
    --bs-breakpoint-#{$name}: #{$value};
  }
}

@media (min-width: 2400px) {
  .col-xxxl-1 {
    flex: 0 0 auto;
    width: 8.33333333%;
  }
  .col-xxxl-11 {
    flex: 0 0 auto;
    width:91.66666667%
  }
}

// Paperless-ngx styles
body, input, select, textarea, button, .ng-select {
  font-family: 'Cairo', sans-serif !important;
}

body {
  --pngx-body-font-size: 0.875rem;
  font-size: var(--pngx-body-font-size);
  height: 100vh;
}

* {
  transition: background-color 0.3s ease, border-color 0.3s ease;
}

@media(min-width: 768px) {
  .col-slim {
    padding-inline-start: calc(50px + $grid-gutter-width) !important;
  }
}

svg.logo {
  .leaf {
    fill: var(--bs-primary) !important;
  }
  .text {
    fill: var(--bs-body-color) !important;
  }
}

.navbar.bg-primary {
  --bs-primary: hsl(var(--pngx-primary),var(--pngx-primary-lightness));
  --bs-primary-rgb: var(--bs-primary);
}

.border {
  border-color: var(--bs-border-color) !important;
}

.border-end {
  border-inline-end: 1px solid var(--bs-border-color) !important;
}

.border-start {
