/*
 * Bootstrap's right-to-left build, for the styles-rtl.scss entry point. Its
 * utilities mirror the default build (`.ms-*` is a margin-right here, not a
 * margin-left), which is why the two builds must never be loaded together.
 */
@import "node_modules/bootstrap/dist/css/bootstrap.rtl.css";

/*
 * Right-to-left counterpart of styles.scss, loaded instead of it for languages
 * that read right-to-left. Which one applies is decided by the document
 * direction set on <html> in documents/templates/index.html.
 */
@use "fonts";
@use "bootstrap-rtl";
@use "app";

/*
 * Web font used across the application. Kept as its own entry point so that it
 * is emitted before Bootstrap in both the left-to-right and right-to-left
 * builds.
 */
